# Create a set of downloaded song IDs from the earlier response
downloaded_song_ids = {55, 66, 13, 8, 301, 24, 188, 28, 240, 198, 7, 313, 57, 298, 289, 195, 51, 94, 95, 9}

# Loop: go to next song until we reach a downloaded song
while True:
    result = apis.spotify.next_song(access_token=access_token)
    print("Next song result:", result)
    # The response should contain song_id of the new current song
    if 'song_id' in result:
        current_song_id = result['song_id']
        if current_song_id in downloaded_song_ids:
            print(f"Reached downloaded song with ID {current_song_id}")
            break
    else:
        # If no song_id, maybe error, break
        print("Error or no song_id in response")
        break

