# Let's search for each song in the archive list and find the matching song IDs.
# We'll search by title and match the artist name.

def find_song_id(title, artist):
    results = apis.spotify.search_songs(query=title, access_token=spotify_token, page_limit=20)
    for song in results:
        # Check if title matches exactly and artist matches
        if song['title'].lower() == title.lower():
            for a in song['artists']:
                if a['name'].lower() == artist.lower():
                    return song['song_id']
    return None

# Find song IDs for all songs to archive
song_ids_to_archive = []
for song in songs_to_archive:
    song_id = find_song_id(song['title'], song['artist'])
    if song_id:
        song_ids_to_archive.append(song_id)
        print(f"Found: {song['title']} by {song['artist']} -> song_id={song_id}")
    else:
        print(f"NOT FOUND: {song['title']} by {song['artist']}")

print(f"\nTotal songs found: {len(song_ids_to_archive)}")
print(f"Song IDs: {song_ids_to_archive}")

