# Verify the Old Songs playlist contains all 18 archived songs
old_songs_playlist = apis.spotify.show_playlist(playlist_id=654, access_token=login_result["access_token"])
old_song_ids = {song["id"] for song in old_songs_playlist["songs"]}
print(f"Old Songs playlist has {len(old_song_ids)} songs")
print(f"All 18 archived songs present: {old_song_ids == archived_song_ids}")

# Also verify no archived songs remain in other playlists
playlists_after = apis.spotify.show_playlist_library(access_token=login_result["access_token"], page_limit=20)
remaining_archived = []
for pl in playlists_after:
    if pl["playlist_id"] != 654:
        for sid in pl["song_ids"]:
            if sid in archived_song_ids:
                remaining_archived.append((pl["playlist_id"], pl["title"], sid))
print(f"Archived songs remaining in other playlists: {remaining_archived}")

