# Let's check all playlists to see which songs they contain.
playlist_ids = [513, 514, 515, 516, 517, 518, 519]
all_playlists = {}
for pid in playlist_ids:
    playlist = apis.spotify.show_playlist(playlist_id=pid, access_token=spotify_login['access_token'])
    all_playlists[pid] = playlist
    print(f"Playlist {pid}: {playlist['title']} - {len(playlist['songs'])} songs")
    for song in playlist['songs']:
        print(f"  Song ID {song['id']}: {song['title']}")

# Let's search for all songs from the list to get their song IDs.
# We'll search for each song and find the exact match.
song_ids = {}
for song in songs_to_archive:
    query = song['title'] + ' ' + ' '.join(song['artists'])
    results = apis.spotify.search_songs(query=query, access_token=spotify_login['access_token'])
    # Find the exact match
    found = None
    for r in results:
        if r['title'].lower() == song['title'].lower():
            # Check if all artists match
            result_artists = [a['name'].lower() for a in r['artists']]
            expected_artists = [a.lower() for a in song['artists']]
            if all(any(ra == ea for ea in expected_artists) for ra in result_artists) and len(result_artists) == len(expected_artists):
                found = r
                break
    if found:
        song_ids[song['title']] = found['song_id']
        print(f"Found: {song['title']} -> ID {found['song_id']}")
    else:
        print(f"NOT FOUND: {song['title']}")

print("All song IDs:", song_ids)

