    # Find the exact match: title and all artists match
    found = None
    for s in result:
        if s['title'].lower() == song['title'].lower():
            # Check artists
            artist_names = [a['name'].lower() for a in s['artists']]
            expected_artists = [a.lower() for a in song['artists']]
            if all(any(exp in art for art in artist_names) for exp in expected_artists):
                found = s
                break
    if found:
        song_ids[song['title']] = found['song_id']
